    align-items: center;
}

.logo {
    font-family: 'Playfair Display', serif;
    font-size: 1.5rem;
    letter-spacing: 2px;
    font-weight: 700;
}

.nav-links {
    display: flex;
    gap: 2rem;
}

.nav-links a {
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.nav-actions {
    display: flex;
    gap: 1.5rem;
}

.nav-actions button {
    background: none;
    border: none;
    color: var(--text-color);
    cursor: pointer;
    position: relative;
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -8px;
    background: var(--accent-color);
    color: var(--bg-color);
    font-size: 0.7rem;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
}

/* Hero */
#hero {
    height: 100vh;
    display: flex;
    align-items: center;
    background: linear-gradient(rgba(0,0,0,0.5), rgba(0,0,0,0.5)), url('https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?auto=format&fit=crop&w=1600&q=80');
    background-size: cover;
    background-position: center;
}

.hero-content {
    max-width: 600px;
}

.eyebrow {
    text-transform: uppercase;
    letter-spacing: 3px;
    font-size: 0.8rem;
    color: var(--text-muted);
}

#hero h1 {
    font-size: 4rem;
    margin: 1rem 0;
}

#hero p {
    font-size: 1.2rem;
    margin-bottom: 2rem;
    color: var(--text-muted);
}

.btn {
    display: inline-block;
    padding: 1rem 2.5rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    transition: all 0.3s;
}

.btn.primary {
    background-color: var(--primary-btn);
    color: var(--primary-btn-text);
}

.btn.primary:hover {
    background-color: #cccccc;
    opacity: 1;
}

/* Sections */
section {
    padding: var(--spacing-lg) 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 3rem;
}

.section-header h2 {
    font-size: 2.5rem;
}

.view-all {
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 1px;
    border-bottom: 1px solid var(--accent-color);
    padding-bottom: 2px;
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    transition: transform 0.3s, border-color 0.3s;
}

.product-card:hover {
    transform: translateY(-5px);
    border-color: #444;
}

.product-image {
    position: relative;
    aspect-ratio: 3/4;
    overflow: hidden;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-badge {
    position: absolute;
    top: 1rem;
    left: 1rem;
    background: var(--accent-color);
    color: var(--bg-color);
    padding: 0.2rem 0.6rem;
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
}

.product-info {
    padding: 1.5rem;
}

.product-info h3 {
    font-family: 'Inter', sans-serif;
    font-size: 1rem;
    margin-bottom: 0.5rem;
    font-weight: 400;
}

.product-price {
    font-weight: 600;
}

.old-price {
    text-decoration: line-through;
    color: var(--text-muted);
    font-weight: 400;
    font-size: 0.9rem;
    margin-right: 0.5rem;
}

/* Deals Section */
.bg-dark-accent {
    background-color: #111111;
}

.deals-layout {
    display: grid;
    grid-template-columns: 1fr 2fr;
    gap: 4rem;
    align-items: center;
}

.deals-info h2 {
    font-size: 3rem;
    margin: 1.5rem 0;
}

.badge {
    background: #d4af37;
    color: #000;
    padding: 0.3rem 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    border-radius: 2px;
}

.countdown {
    display: flex;
    gap: 1.5rem;
    margin-top: 2rem;
}

.time-part {
    text-align: center;
    font-size: 0.8rem;
    color: var(--text-muted);
}

.time-part span {
    display: block;
    font-size: 2rem;
    color: var(--text-color);
    font-weight: 600;
}

/* Editorial Grid */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    grid-template-rows: repeat(2, 300px);
    gap: 1.5rem;
}

.editorial-card {
    position: relative;
    overflow: hidden;
}

.editorial-card.large {
    grid-row: span 2;
}

.editorial-card img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.card-overlay {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    padding: 2rem;
    background: linear-gradient(transparent, rgba(0,0,0,0.8));
}

.card-overlay h3 {
    font-size: 1.5rem;
    margin-bottom: 0.5rem;
}

.card-overlay p {
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

.link {
    display: inline-block;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 1px;
    font-weight: 600;
    border-bottom: 1px solid var(--accent-color);
}

/* Footer */
footer {
    background: #050505;
    padding: 4rem 0 2rem;
    border-top: 1px solid var(--border-color);
    margin-top: 4rem;
}

.footer-content {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .logo {
    margin-bottom: 1rem;
}

.footer-brand p {
    color: var(--text-muted);
}

.footer-links {
    display: flex;
    gap: 4rem;
}

.link-group h4 {
    margin-bottom: 1.5rem;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.link-group ul li {
    margin-bottom: 0.8rem;
}

.link-group ul a {
    color: var(--text-muted);
    font-size: 0.9rem;
}

.footer-newsletter h4 {
    margin-bottom: 1.5rem;
    font-size: 0.9rem;
    text-transform: uppercase;
}

#newsletter-form {
    display: flex;
    gap: 0.5rem;
}

#newsletter-form input {
    background: #111;
    border: 1px solid var(--border-color);
    padding: 0.8rem;
    color: #fff;
    flex-grow: 1;
}

#newsletter-form button {
    background: #fff;
    color: #000;
    border: none;
    padding: 0 1.5rem;
    font-weight: 600;
    cursor: pointer;
}

.footer-bottom {
    border-top: 1px solid var(--border-color);
    padding-top: 2rem;
    color: var(--text-muted);
    font-size: 0.8rem;
}

/* Responsive */
@media (max-width: 968px) {
    .deals-layout {
        grid-template-columns: 1fr;
