        badge: ""
    },
    {
        id: 3,
        name: "Architectural Table Lamp",
        price: 320,
        image: "https://images.unsplash.com/photo-1507473885765-e6ed057f782c?auto=format&fit=crop&w=600&q=80",
        badge: "Limited"
    },
    {
        id: 4,
        name: "Weighted Linen Throw",
        price: 150,
        image: "https://images.unsplash.com/photo-1583847268964-b28dc2f51f92?auto=format&fit=crop&w=600&q=80",
        badge: ""
    }
];

const dealProducts = [
    {
        id: 5,
        name: "Premium Wireless Headphones",
        price: 299,
        oldPrice: 399,
        image: "https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=600&q=80",
        badge: "25% OFF"
    },
    {
        id: 6,
        name: "Silver Essential Ring",
        price: 85,
        oldPrice: 120,
        image: "https://images.unsplash.com/photo-1611085583191-a3b1a3089691?auto=format&fit=crop&w=600&q=80",
        badge: "Sale"
    }
];

// DOM Elements
const featuredGrid = document.getElementById('featured-grid');
const dealsGrid = document.getElementById('deals-grid');
const cartCount = document.querySelector('.cart-count');
const newsletterForm = document.getElementById('newsletter-form');

// Functions
function renderProducts(products, container) {
    container.innerHTML = products.map(product => `
        <div class="product-card">
            <div class="product-image">
                ${product.badge ? `<span class="product-badge">${product.badge}</span>` : ''}
                <img src="${product.image}" alt="${product.name}">
            </div>
            <div class="product-info">
                <h3>${product.name}</h3>
                <div class="product-price">
                    ${product.oldPrice ? `<span class="old-price">$${product.oldPrice}</span>` : ''}
                    <span>$${product.price}</span>
                </div>
                <button class="add-to-cart" data-id="${product.id}" style="margin-top: 1rem; background: none; border: 1px solid #444; color: #fff; padding: 0.5rem 1rem; width: 100%; cursor: pointer; transition: all 0.3s;">Add to Cart</button>
            </div>
        </div>
    `).join('');
}

// Cart State
let count = 0;
function updateCart() {
    count++;
    cartCount.textContent = count;
    cartCount.style.transform = 'scale(1.2)';
    setTimeout(() => {
        cartCount.style.transform = 'scale(1)';
    }, 200);
}

// Event Listeners
document.addEventListener('DOMContentLoaded', () => {
    renderProducts(featuredProducts, featuredGrid);
    renderProducts(dealProducts, dealsGrid);

    // Delegate cart clicks
    document.addEventListener('click', (e) => {
        if (e.target.classList.contains('add-to-cart')) {
            updateCart();
            const btn = e.target;
            const originalText = btn.textContent;
            btn.textContent = 'Added';
            btn.style.borderColor = '#fff';
            setTimeout(() => {
                btn.textContent = originalText;
                btn.style.borderColor = '#444';
            }, 1000);
        }
    });

    // Newsletter
    newsletterForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const email = newsletterForm.querySelector('input').value;
        alert(`Thank you! ${email} has been subscribed to our newsletter.`);
        newsletterForm.reset();
    });

    // Countdown Timer Mock
    let hours = 12, minutes = 45, seconds = 30;
    const countdownEls = document.querySelectorAll('#countdown .time-part span');

    setInterval(() => {
        seconds--;
        if (seconds < 0) {
            seconds = 59;
            minutes--;
        }
        if (minutes < 0) {
            minutes = 59;
            hours--;
        }
        if (hours < 0) {
            hours = 0; minutes = 0; seconds = 0;
        }

        countdownEls[0].textContent = hours.toString().padStart(2, '0');
        countdownEls[1].textContent = minutes.toString().padStart(2, '0');
        countdownEls[2].textContent = seconds.toString().padStart(2, '0');
    }, 1000);

    // Scroll Header Effect
    window.addEventListener('scroll', () => {
        const header = document.querySelector('header');
        if (window.scrollY > 50) {
            header.style.padding = '0.5rem 0';
            header.style.background = 'rgba(10, 10, 10, 0.95)';
        } else {
            header.style.padding = '0';
            header.style.background = 'rgba(10, 10, 10, 0.8)';
        }
    });
});
