    top: 1rem;
    left: 1rem;
    background: var(--accent-color);
    color: var(--bg-color);
    padding: 0.2rem 0.6rem;
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
}

.product-info {
    padding: 1.5rem;
}

.product-info h3 {
    font-family: 'Inter', sans-serif;
    font-size: 1rem;
    margin-bottom: 0.5rem;
    font-weight: 400;
}

.product-price {
    font-weight: 600;
}

.old-price {
    text-decoration: line-through;
    color: var(--text-muted);
    font-weight: 400;
    font-size: 0.9rem;
    margin-right: 0.5rem;
}

/* Deals Section */
.bg-dark-accent {
    background-color: #111111;
}

.deals-layout {
    display: grid;
    grid-template-columns: 1fr 2fr;
    gap: 4rem;
    align-items: center;
}

.deals-info h2 {
    font-size: 3rem;
    margin: 1.5rem 0;
}

.badge {
    background: #d4af37;
    color: #000;
    padding: 0.3rem 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    border-radius: 2px;
}

.countdown {
    display: flex;
    gap: 1.5rem;
    margin-top: 2rem;
}

.time-part {
    text-align: center;
    font-size: 0.8rem;
    color: var(--text-muted);
}

.time-part span {
    display: block;
    font-size: 2rem;
    color: var(--text-color);
    font-weight: 600;
}

/* Editorial Grid */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    grid-template-rows: repeat(2, 300px);
    gap: 1.5rem;
}

.editorial-card {
    position: relative;
    overflow: hidden;
}

.editorial-card.large {
    grid-row: span 2;
}

.editorial-card img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.card-overlay {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    padding: 2rem;
    background: linear-gradient(transparent, rgba(0,0,0,0.8));
}

.card-overlay h3 {
    font-size: 1.5rem;
    margin-bottom: 0.5rem;
}

.card-overlay p {
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

.link {
    display: inline-block;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 1px;
    font-weight: 600;
    border-bottom: 1px solid var(--accent-color);
}

/* Footer */
footer {
    background: #050505;
    padding: 4rem 0 2rem;
    border-top: 1px solid var(--border-color);
    margin-top: 4rem;
}

.footer-content {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .logo {
    margin-bottom: 1rem;
}

.footer-brand p {
    color: var(--text-muted);
}

.footer-links {
    display: flex;
    gap: 4rem;
}

.link-group h4 {
    margin-bottom: 1.5rem;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.link-group ul li {
    margin-bottom: 0.8rem;
}

.link-group ul a {
    color: var(--text-muted);
    font-size: 0.9rem;
}

.footer-newsletter h4 {
    margin-bottom: 1.5rem;
    font-size: 0.9rem;
    text-transform: uppercase;
}

#newsletter-form {
    display: flex;
    gap: 0.5rem;
}

#newsletter-form input {
    background: #111;
    border: 1px solid var(--border-color);
    padding: 0.8rem;
    color: #fff;
    flex-grow: 1;
}

#newsletter-form button {
    background: #fff;
    color: #000;
    border: none;
    padding: 0 1.5rem;
    font-weight: 600;
    cursor: pointer;
}

.footer-bottom {
    border-top: 1px solid var(--border-color);
    padding-top: 2rem;
    color: var(--text-muted);
    font-size: 0.8rem;
}

/* Responsive */
@media (max-width: 968px) {
    .deals-layout {
        grid-template-columns: 1fr;
    }
    .footer-content {
        grid-template-columns: 1fr 1fr;
    }
    #hero h1 {
        font-size: 3rem;
    }
}

@media (max-width: 768px) {
    .nav-links {
        display: none;
    }
    .editorial-grid {
        grid-template-columns: 1fr;
        grid-template-rows: auto;
    }
    .editorial-card.large {
        grid-row: auto;
        height: 400px;
    }
    .footer-content {
        grid-template-columns: 1fr;
        gap: 2rem;
    }
}
